using System.Text.Json;
using System.Text.Json.Nodes;
using K9.Api.Assessments;

namespace K9.Api.Tests.Infrastructure;

/// <summary>
/// The Prowler OCSF fixtures generated by tools/prowler-fixtures, and helpers to derive
/// invalid variants from them.
/// </summary>
public static class ProwlerFixtures
{
    public const string ProwlerVersion = "5.44.0";

    public const string BaselineA = "aws-a-t1-baseline";
    public const string FollowupA = "aws-a-t2-followup";
    public const string ReexportA = "aws-a-t2-reexport";
    public const string ThirdA = "aws-a-t3-third";
    public const string ConflictA = "aws-a-t2-conflict";
    public const string BaselineB = "aws-b-t1-baseline";
    public const string MultiAccount = "aws-multi-account";
    public const string UidCollision = "aws-prowler-uid-collision";
    public const string InFileDuplicate = "aws-in-file-duplicate";
    public const string InFileContradiction = "aws-in-file-contradiction";
    public const string AzureUnsupported = "azure-unsupported";

    public const string AccountA = "111111111111";
    public const string AccountB = "222222222222";

    public static readonly DateTimeOffset T1 = new(2026, 9, 1, 10, 0, 0, TimeSpan.Zero);
    public static readonly DateTimeOffset T2 = new(2026, 9, 8, 10, 0, 0, TimeSpan.Zero);
    public static readonly DateTimeOffset T3 = new(2026, 9, 15, 10, 0, 0, TimeSpan.Zero);

    public const string BucketCheck = "s3_bucket_level_public_access_block";
    public const string SecurityGroupCheck = "ec2_securitygroup_allow_ingress_from_internet_to_all_ports";
    public const string RootMfaCheck = "iam_root_mfa_enabled";
    public const string KeyRotationCheck = "iam_rotate_access_key_90_days";
    public const string AmiBlockCheck = "ec2_ami_account_block_public_access";
    public const string ContactsCheck = "account_maintain_current_contact_details";

    public static IEnumerable<string> All() =>
        JsonNode.Parse(File.ReadAllBytes(PathOf("manifest.json")))!["fixtures"]!.AsArray()
            .Select(f => f!["file"]!.GetValue<string>().Replace(".ocsf.json", "", StringComparison.Ordinal));

    public static byte[] Bytes(string fixture) => File.ReadAllBytes(PathOf($"{fixture}.ocsf.json"));

    public static JsonArray Load(string fixture) => JsonNode.Parse(Bytes(fixture))!.AsArray();

    public static byte[] Serialize(JsonArray findings) => JsonSerializer.SerializeToUtf8Bytes(findings);

    /// <summary>The fixture with <paramref name="change"/> applied, re-serialized.</summary>
    public static byte[] Mutate(string fixture, Action<JsonArray> change)
    {
        var findings = Load(fixture);
        change(findings);
        return Serialize(findings);
    }

    /// <summary>The first finding of the fixture with <paramref name="change"/> applied to it.</summary>
    public static byte[] MutateFirst(string fixture, Action<JsonObject> change) =>
        Mutate(fixture, findings => change(findings[0]!.AsObject()));

    /// <summary>Concatenates the findings of several fixtures into one file.</summary>
    public static byte[] Combine(params string[] fixtures) =>
        Serialize(new JsonArray(fixtures.SelectMany(f => Load(f)).Select(n => n!.DeepClone()).ToArray()));

    public static JsonObject Find(JsonArray findings, string checkId, string? resourceName = null, string? region = null) =>
        findings.Select(f => f!.AsObject()).Single(f =>
            f["metadata"]!["event_code"]!.GetValue<string>() == checkId
            && (resourceName is null || f["resources"]![0]!["name"]!.GetValue<string>() == resourceName)
            && (region is null || f["resources"]![0]!["region"]!.GetValue<string>() == region));

    public static Task<ReadResult> ReadAsync(byte[] file, AssessmentImportOptions? limits = null) =>
        ProwlerOcsfReader.ReadAsync(new MemoryStream(file), limits ?? new AssessmentImportOptions());

    public static async Task<IReadOnlyList<ParsedObservation>> ReadValidAsync(string fixture)
    {
        var result = await ReadAsync(Bytes(fixture));
        Assert.True(result.Succeeded, $"{fixture} was rejected: {string.Join(", ", result.Problems)}");
        return result.Observations;
    }

    private static string PathOf(string file) =>
        Path.Combine(AppContext.BaseDirectory, "Fixtures", "Prowler", ProwlerVersion, file);
}

/// <summary>Observations built directly, for tests that must not depend on the reader.</summary>
public static class Observations
{
    public static ParsedObservation Sample(int index = 0) => new()
    {
        Index = index,
        Provider = "aws",
        AccountUid = ProwlerFixtures.AccountA,
        CheckId = ProwlerFixtures.BucketCheck,
        Location = "eu-west-1",
        ResourceUid = "arn:aws:s3:::k9-logs",
        ResourceName = "k9-logs",
        ScanTime = ProwlerFixtures.T1,
        Result = CheckResult.Fail,
        Muted = false,
        SeverityId = 4,
        StatusDetail = "Block Public Access is not configured for the S3 Bucket k9-logs.",
        ResourceType = "AwsS3Bucket",
        Title = "S3 bucket has Block Public Access enabled",
        Severity = "High",
        Remediation = "Enable Block Public Access.",
        ProwlerFindingUid = "prowler-aws-s3_bucket_level_public_access_block-111111111111-eu-west-1-k9-logs",
        ProwlerScanId = "01a05c69-4d00-7226-b63c-5ab791b7584a",
        ProwlerVersion = "5.44.0",
        OcsfVersion = "1.5.0",
    };
}
